  notify:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Notify dev channel
        uses: actions/github-script@v6
        with:
          script: |
            const commitMessage = github.event.head_commit.message;
            const mergeRegex = /Merge pull request #([0-9]+)/;
            const match = commitMessage.match(mergeRegex);
            if (!match) {
              core.info('No merge commit detected. Exiting.');
              return;
            }
            const prNumber = parseInt(match[1], 10);
            core.info(`Detected PR #${prNumber}`);

            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });

            const prBody = pr.body || '';
            const issueRegex = /(Closes|Fixes|Resolves)\s+#([0-9]+)/gi;
            const issues = [];
            let m;
            while ((m = issueRegex.exec(prBody)) !== null) {
              issues.push(parseInt(m[2], 10));
            }

